# -*- coding: utf-8 -*-
# (speaker, spanish, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
L, B, I, A, C = "Lucas", "Borja", "Irene", "Amparo", "Camarero"
D = [
("#", "Escena 1 · Miércoles 20 de mayo, 9:30 · Sede de Meridia Capital, calle Serrano, Madrid", "장면 1 · 5월 20일 수요일 오전 9시 30분 · 마드리드 세라노 거리, 메리디아 캐피털 본사"),
(None, "Lucas ha llegado en el primer AVE desde Castellón. Planta novena: cristal, moqueta gris, un cuadro abstracto que nadie mira. Borja Valcárcel, cincuenta y dos años, camisa blanca sin corbata, sale a recibirlo con los brazos abiertos.", "루카스는 카스테욘발 첫 고속열차로 왔다. 9층. 유리벽, 회색 카펫, 아무도 보지 않는 추상화. 쉰두 살의 보르하 발카르셀이 넥타이 없는 흰 셔츠 차림으로 팔을 벌리며 마중 나온다."),
(B, "¡Lucas Ferrer! Míralo, moreno del sol de Riad. Pasa, pasa. ¿Un café?", "루카스 페레르! 이것 봐, 리야드 햇볕에 그을렸네. 들어와, 들어와. 커피?"),
(L, "Un cortado, gracias. Hola, Borja. Cuánto tiempo.", "코르타도 한 잔이요, 고마워요. 안녕하세요, 보르하. 오랜만이에요."),
(B, "Dos años y medio. Te fuiste un viernes, sin despedida. Todavía me lo echan en cara en la oficina.", "2년 반이지. 넌 금요일에 작별 인사도 없이 떠났어. 사무실에선 아직도 나한테 그 얘길 해."),
(L, "No me gustan las despedidas. Y aquel viernes no tenía mucho que celebrar.", "작별 인사는 싫어해요. 그리고 그 금요일엔 축하할 게 별로 없었어요."),
(B, "Ya. L'Alcora. (pausa) Siéntate. No te he llamado para hablar del pasado.", "그래. 라르코라. (잠시 멈추고) 앉아. 과거 얘기를 하려고 부른 건 아니야."),
(L, "Por teléfono dijiste «una oportunidad que no te vas a creer». Aquí estoy.", "전화로 '믿기 힘든 기회'라고 했잖아요. 그래서 왔어요."),
(B, "Primero, enhorabuena. México, Miami, Texas, Bogotá y ahora un lote en Riad. Se habla de ti en el sector, ¿lo sabías?", "우선 축하해. 멕시코, 마이애미, 텍사스, 보고타, 이제 리야드 로트까지. 업계에서 네 얘기가 나와. 알고 있었어?"),
(L, "Se habla de Albalat. Yo solo hago las maletas.", "알발라트 얘기가 나오는 거죠. 저는 짐만 싸요."),
(B, "No seas modesto, que no te pega. Te lo resumo: ya no estoy en la consultora. Desde enero soy socio de Meridia Capital.", "겸손 떨지 마, 너한테 안 어울려. 짧게 말할게. 난 이제 컨설팅 회사에 없어. 1월부터 메리디아 캐피털의 파트너야."),
(L, "Meridia. (deja la taza en el plato) Meridia es el fondo que compró l'Alcora.", "메리디아. (잔을 받침에 내려놓으며) 메리디아는 라르코라를 산 펀드잖아요."),
(B, "Somos el fondo que compró l'Alcora, sí. Y hemos aprendido de aquello. Esto es otro tipo de operación.", "우리가 라르코라를 산 펀드 맞아. 그리고 그 일에서 배웠어. 이번엔 다른 종류의 거래야."),
(L, "¿Qué operación?", "무슨 거래요?"),
(B, "Queremos entrar en Cerámicas Albalat. Con el sesenta por ciento.", "세라미카스 알발라트에 들어가고 싶어. 지분 60%로."),
(None, "Lucas no contesta enseguida. Por la ventana se oye, muy lejos, el tráfico de Serrano.", "루카스는 바로 대답하지 않는다. 창밖으로 세라노 거리의 차 소리가 아주 멀리 들린다."),
(L, "Albalat no está en venta.", "알발라트는 팔려고 내놓은 회사가 아니에요."),
(B, "Todo está en venta, Lucas. Solo cambia el precio. Y el precio es bueno: valoramos la empresa en cuarenta y dos millones. Por el sesenta por ciento, veinticinco millones doscientos mil euros.", "모든 건 팔려고 있어, 루카스. 값만 다를 뿐이지. 그리고 값은 좋아. 회사 가치를 4,200만 유로로 봐. 60%면 2,520만 유로."),
(L, "¿Con qué cifras?", "어떤 숫자로요?"),
(B, "Con las públicas: Registro Mercantil, prensa y lo que cuentan vuestros clientes. Facturasteis sesenta y dos millones hace dos años; este año rondaréis los setenta y cuatro. Un EBITDA de unos seis.", "공개된 숫자로. 상업등기소, 언론, 그리고 너희 고객들이 하는 말. 2년 전 매출이 6,200만이었지. 올해는 7,400만쯤 되겠고. 상각 전 영업이익은 600만 정도."),
(L, "Está bien informado el fondo.", "펀드가 정보가 빠르네요."),
(B, "Es nuestro trabajo. Y ahora viene lo mejor: queremos que la dirijas tú. Consejero delegado. Doscientos ochenta mil fijos, bonus y un dos por ciento en opciones.", "그게 우리 일이야. 이제 제일 좋은 부분. 회사를 네가 이끌었으면 해. 대표이사. 고정 연봉 28만, 보너스, 그리고 스톡옵션 2%."),
(L, "(sonríe sin alegría) Hace tres años no me habrías dado ni un despacho con ventana.", "(기쁘지 않은 미소로) 3년 전이었으면 창문 있는 방 하나도 안 줬을 거면서."),
(B, "Hace tres años eras un analista con talento. Hoy eres el hombre que ha abierto cinco mercados en dieciocho meses. Si no hubiera sido por ti, Albalat seguiría vendiendo a BricoHogar con descuento.", "3년 전엔 재능 있는 분석가였지. 지금은 18개월 만에 시장 다섯 개를 연 사람이고. 네가 아니었다면 알발라트는 아직도 브리코오가르에 할인해서 팔고 있을 거야."),
(L, "Si no hubiera sido por Pepe, por Amparo, por Vicente y por trescientas cincuenta personas, yo seguiría haciendo Excels en esta misma calle.", "페페, 암파로, 비센테, 그리고 350명이 아니었다면, 전 아직도 바로 이 거리에서 엑셀이나 만들고 있었을 거예요."),
(B, "Precioso. Guárdalo para la junta de accionistas. Nosotros ponemos el capital para crecer: un horno nuevo, una filial en Estados Unidos, una oficina en Seúl.", "멋지네. 그건 주주총회용으로 아껴 둬. 우린 성장을 위한 자본을 넣어. 새 가마, 미국 자회사, 서울 사무소."),
(L, "¿Y qué quitáis?", "그럼 뭘 빼요?"),
(B, "(abre una carpeta azul) Racionalizamos. El horno dos hace producto nacional de poco margen. Eso se externaliza, a Portugal o a Turquía. La marca se queda en Onda.", "(파란 서류철을 펼치며) 합리화하지. 2호기는 마진이 낮은 국내용 제품을 만들어. 그건 포르투갈이나 튀르키예에 외주로 넘겨. 브랜드는 온다에 남고."),
(L, "El horno dos son ochenta y siete personas.", "2호기면 여든일곱 명이에요."),
(B, "Que se recolocan en el uno y en el tres. Las que se puedan.", "1호기와 3호기로 재배치하지. 할 수 있는 만큼은."),
(L, "«Las que se puedan». Eso mismo pusimos en la página doce del informe de l'Alcora.", "'할 수 있는 만큼'. 라르코라 보고서 12쪽에 우리가 쓴 말이랑 똑같네요."),
(B, "Y l'Alcora habría cerrado igual, con nosotros o sin nosotros. Lo sabes.", "라르코라는 우리가 있든 없든 문을 닫았을 거야. 너도 알잖아."),
(L, "No lo sé. Nunca lo sabré. Ese es el problema.", "몰라요. 영원히 모를 거예요. 그게 문제예요."),
(B, "Lucas, el sentimentalismo no paga nóminas. Los fondos, sí.", "루카스, 감상은 월급을 못 줘. 펀드는 주지."),
(L, "Los fondos pagan dividendos, Borja. Las nóminas las paga la fábrica.", "펀드는 배당금을 줘요, 보르하. 월급은 공장이 주고요."),
(B, "(ríe) Sigues teniendo respuesta para todo. Eso no lo has perdido en Onda.", "(웃으며) 여전히 뭐든 받아치네. 그건 온다에서도 안 잃어버렸구나."),
(L, "Una pregunta. ¿Meridia había hablado antes con Vicente Albalat?", "하나만 물을게요. 메리디아가 전에 비센테 알발라트와 얘기한 적 있어요?"),
(B, "(una pausa muy breve) Hace dos años. Antes de mi época. Un socio fue a Onda; el señor Albalat lo escuchó y le dijo que no. Muy educado, según me contaron.", "(아주 짧은 침묵) 2년 전에. 내가 오기 전이야. 파트너 한 명이 온다에 갔지. 알발라트 씨는 들어 보고 거절했대. 아주 정중하게, 라고 들었어."),
(L, "Tres semanas sin dormir. Muy educado.", "3주 동안 잠을 못 잤대요. 아주 정중하게."),
(B, "¿Perdona?", "뭐라고?"),
(L, "Nada. ¿Y por qué volvéis ahora?", "아무것도 아니에요. 그런데 왜 지금 다시 와요?"),
(B, "Porque ahora la empresa vale casi el doble. Y porque ahora estás tú dentro. Conoces a la familia, y la familia te escucha.", "지금은 회사 가치가 거의 두 배니까. 그리고 지금은 네가 안에 있으니까. 넌 가족을 알고, 가족은 네 말을 들어."),
(L, "O sea, que no me queréis como capitán. Me queréis como puerta.", "그러니까 저를 선장이 아니라 문으로 쓰고 싶은 거네요."),
(B, "Te queremos de capitán. La puerta ya la tenemos. Xavier, el sobrino, tiene un quince por ciento y ganas de vender. Teresa, la hermana, un veinte, y dudas.", "선장으로 원해. 문은 이미 있어. 조카 하비에르가 15%를 갖고 있고 팔고 싶어 해. 누나 테레사는 20%에 고민 중이고."),
(L, "¿Cómo sabéis eso?", "그걸 어떻게 알아요?"),
(B, "Lejos de escondérnoslo, Xavier nos llamó él mismo. En marzo, cuando salió lo de Riad en la prensa de Castellón.", "숨기기는커녕 하비에르가 직접 전화했어. 3월에 리야드 건이 카스테욘 신문에 났을 때."),
(L, "(se levanta) Gracias por el café, Borja.", "(일어나며) 커피 고마워요, 보르하."),
(B, "Siéntate, hombre. No te pido una respuesta hoy. Pero la junta familiar es en junio, y antes de la junta mandaré la oferta por escrito. A todos los accionistas.", "앉아, 이 친구야. 오늘 대답하라는 거 아니야. 하지만 가족 주주총회가 6월이고, 그 전에 서면으로 제안서를 보낼 거야. 모든 주주에게."),
(L, "Antes de que la mandes, que conste una cosa: no voy a hacer de puerta.", "보내기 전에 이것만은 분명히 해 두죠. 저는 문 노릇은 안 해요."),
(B, "No te precipites. Esta noche cena con Irene; sigue en la consultora y te tiene cariño. Mañana a las nueve te espero aquí.", "서두르지 마. 오늘 밤엔 이레네랑 저녁 먹어. 아직 컨설팅 회사에 있고, 너를 아껴. 내일 9시에 여기서 기다릴게."),

("#", "Escena 2 · 21:30 · Una terraza en Chueca", "장면 2 · 밤 9시 30분 · 추에카의 한 테라스"),
(None, "Una plaza pequeña, mesas de metal, ruido de vasos. Irene Sáez, treinta y seis años, compañera de Lucas durante seis años en la consultora, llega con el portátil todavía colgado del hombro.", "작은 광장, 철제 테이블, 잔 부딪히는 소리. 컨설팅 회사에서 루카스와 6년을 함께한 서른여섯 살의 이레네 사에스가 노트북 가방을 아직 어깨에 멘 채 도착한다."),
(I, "¡Pero bueno! El desaparecido. Déjame verte. Estás más delgado y más tranquilo. No sé qué me da más envidia.", "세상에! 실종자께서. 좀 보자. 살도 빠졌고 더 차분해졌네. 뭐가 더 부러운지 모르겠다."),
(L, "Hola, Irene. Tú estás igual. Con el portátil.", "안녕, 이레네. 넌 그대로네. 노트북까지."),
(I, "El portátil es parte de mi cuerpo. Ya lo sabes. ¿Qué tomas?", "노트북은 내 몸의 일부야. 알잖아. 뭐 마실래?"),
(C, "Buenas noches. ¿Qué les pongo?", "안녕하세요. 뭐 드릴까요?"),
(L, "Una caña, por favor. Y unas bravas para compartir.", "생맥주 한 잔이요. 그리고 나눠 먹을 브라바스 하나요."),
(I, "Para mí un vermú. (al camarero) Gracias. (a Lucas) Vienes de ver a Borja, ¿verdad? En la consultora no se habla de otra cosa.", "난 베르무트. (종업원에게) 고마워요. (루카스에게) 보르하 만나고 오는 길이지? 회사에선 그 얘기뿐이야."),
(L, "¿Tanto se nota?", "그렇게 티가 나?"),
(I, "Borja me pidió que cenara contigo. Que te recordara lo bien que se vive en Madrid. Así que, oficialmente, esta es una cena de trabajo.", "보르하가 너랑 저녁 먹으라고 했어. 마드리드 생활이 얼마나 좋은지 상기시켜 주라고. 그러니까 공식적으로는 이건 업무 저녁이야."),
(L, "¿Y extraoficialmente?", "비공식적으로는?"),
(I, "Extraoficialmente, quiero saber si eres feliz. Te fuiste sin decir nada y luego te vi en una foto de LinkedIn, con casco, en una obra de Monterrey.", "비공식적으로는, 네가 행복한지 알고 싶어. 아무 말 없이 떠나더니, 나중에 링크드인 사진에서 봤어. 안전모 쓰고 몬테레이 공사 현장에 있더라."),
(L, "Soy feliz cuando sale bien un contenedor. Y cuando sale mal, aprendo algo. Antes no aprendía nada; solo cambiaba de cliente.", "컨테이너 하나가 잘 나가면 행복해. 잘못되면 뭔가 배우고. 예전엔 아무것도 안 배웠어. 고객만 바꿨지."),
(C, "Aquí tienen: la caña, el vermú y las bravas.", "여기 있습니다. 생맥주, 베르무트, 브라바스요."),
(I, "Gracias. (pincha una patata) Te voy a contar algo que Borja no te ha contado. ¿Sabes qué pasó con l'Alcora después?", "고마워요. (감자를 하나 찍으며) 보르하가 말 안 한 걸 말해 줄게. 라르코라가 그 뒤에 어떻게 됐는지 알아?"),
(L, "Cerraron la fábrica. Eso lo sé.", "공장을 닫았지. 그건 알아."),
(I, "Y la marca la siguen vendiendo. Fabricada en Turquía, con la misma caja y el mismo nombre de pueblo. Las baldosas «de l'Alcora» no han visto l'Alcora en su vida.", "브랜드는 아직 팔아. 튀르키예에서 만들어서, 같은 상자에 같은 마을 이름을 붙여서. '라르코라' 타일이 평생 라르코라를 본 적이 없는 거지."),
(L, "(tarda en responder) No lo sabía.", "(한참 뒤에 대답하며) 몰랐어."),
(I, "Nadie lo cuenta. Queda mal en las presentaciones. Por eso te lo cuento yo.", "아무도 얘기 안 해. 발표 자료에 넣기엔 모양이 안 좋거든. 그래서 내가 말해 주는 거야."),
(L, "Borja quiere hacer lo mismo con el horno dos. Producto nacional fuera, marca dentro.", "보르하는 2호기에 똑같은 걸 하려고 해. 국내용 제품은 밖으로, 브랜드는 안에."),
(I, "Claro que sí. Es su receta. Funciona en Excel, y no solo en Excel; a veces funciona de verdad. Pero no es tu receta.", "당연하지. 그게 그 사람 레시피야. 엑셀에선 통하고, 엑셀에서만 통하는 것도 아니야. 가끔은 진짜로 통해. 하지만 그건 네 레시피가 아니야."),
(L, "¿Y tú qué harías en mi lugar?", "넌 내 입장이면 어떻게 할 거야?"),
(I, "Yo habría aceptado ya, y me habría comprado un piso en Chamberí. Pero yo no me fui un viernes sin despedirme. Tú sí. Algo te pasaba.", "난 벌써 받아들이고 참베리에 집 한 채 샀겠지. 근데 난 금요일에 인사도 없이 떠나진 않았어. 넌 그랬지. 뭔가 있었던 거야."),
(L, "Me pasaba que no quería volver a firmar algo que no podría explicar delante de ciento ochenta personas.", "180명 앞에서 설명할 수 없는 걸 다시는 서명하고 싶지 않았던 거야."),
(I, "Pues ya está. Ahí tienes tu respuesta. (levanta el vermú) Y no me mires así, que yo cobro igual tanto si dices que sí como si dices que no.", "그럼 됐네. 거기 답이 있잖아. (베르무트를 들며) 그렇게 보지 마. 네가 예라고 하든 아니라고 하든 내 월급은 똑같으니까."),
(L, "Gracias, Irene. De verdad.", "고마워, 이레네. 진심으로."),
(I, "Una condición. Si algún día abres la oficina de Seúl, me invitas a la inauguración.", "조건 하나. 언젠가 서울 사무소를 열면 개소식에 나 초대해."),
(L, "Hecho. Aunque allí las inauguraciones acaban en karaoke.", "좋아. 거기선 개소식이 노래방으로 끝나긴 하지만."),
(I, "Mejor todavía. ¡Camarero! La cuenta, por favor.", "더 좋지. 저기요! 계산서 주세요."),
(C, "Ahora mismo se la traigo.", "바로 갖다 드릴게요."),
(I, "Esta la paga Meridia, que para eso es una cena de trabajo.", "이건 메리디아가 내. 업무 저녁이니까."),
(L, "Pues dale las gracias a Borja de mi parte.", "그럼 내 대신 보르하한테 고맙다고 전해 줘."),
(I, "Se las daré. Y le diré que te he visto contento. Eso no le va a gustar nada.", "전할게. 그리고 네가 행복해 보였다고 말할 거야. 그건 그 사람이 하나도 안 좋아하겠지만."),

("#", "Escena 3 · 23:50 · Habitación de hotel, Gran Vía", "장면 3 · 밤 11시 50분 · 그란비아의 호텔 방"),
(None, "Lucas se sienta en la cama sin quitarse los zapatos. En la mesilla, la carpeta azul de Meridia. Marca un número de Onda. Al tercer tono, contesta Amparo.", "루카스는 신발도 벗지 않고 침대에 앉는다. 협탁 위에 메리디아의 파란 서류철. 온다 번호를 누른다. 세 번째 신호음에 암파로가 받는다."),
(A, "¿Lucas? Son casi las doce. ¿Ha pasado algo?", "루카스? 거의 12시예요. 무슨 일 있어요?"),
(L, "Perdona la hora. Te llamo porque te lo prometí en Monterrey: nada importante sin contártelo antes. Y esto es importante.", "늦게 미안해요. 몬테레이에서 약속했으니까 전화하는 거예요. 중요한 일은 먼저 말하기로. 그리고 이건 중요해요."),
(A, "Te escucho.", "듣고 있어요."),
(L, "Meridia Capital quiere comprar el sesenta por ciento de Albalat. Valoran la empresa en cuarenta y dos millones. Y me ofrecen dirigirla.", "메리디아 캐피털이 알발라트 지분 60%를 사고 싶어 해요. 회사 가치를 4,200만으로 봐요. 그리고 저한테 경영을 맡기겠대요."),
(A, "(silencio) ¿Meridia? Ese nombre...", "(침묵) 메리디아? 그 이름…"),
(L, "Es el grupo que fue a ver a tu padre hace dos años. Me lo ha confirmado Borja. Y es el mismo fondo que cerró l'Alcora. El del Excel.", "2년 전에 아버님을 찾아간 그 그룹이에요. 보르하가 확인해 줬어요. 그리고 라르코라를 닫은 바로 그 펀드예요. 그 엑셀의 펀드."),
(A, "Las tres semanas sin dormir. (pausa) ¿Y tú qué les has dicho?", "3주 동안 못 잔 그거. (잠시) 그래서 당신은 뭐라고 했어요?"),
(L, "Que no voy a hacer de puerta. Pero hay más: Xavier los llamó en marzo. Quiere vender su quince por ciento. Y van a mandar la oferta por escrito a todos los accionistas antes de la junta.", "문 노릇은 안 하겠다고요. 그런데 더 있어요. 하비에르가 3월에 그 사람들한테 전화했대요. 15%를 팔고 싶대요. 그리고 주주총회 전에 모든 주주에게 서면 제안서를 보낸대요."),
(A, "Xavier. Claro. Lleva años diciendo que la cerámica es un negocio del siglo pasado. Y la tía Teresa...", "하비에르. 그렇겠지. 몇 년째 타일은 지난 세기 사업이라고 했으니까. 그리고 테레사 고모는…"),
(L, "Borja dice que tiene dudas.", "보르하는 고민 중이라고 하더라고요."),
(A, "Tiene dos hijos en la universidad y una casa en Valencia que se le cae a trozos. Dudas, sí.", "대학생 아이가 둘이고, 발렌시아 집은 무너져 가요. 고민할 만하죠."),
(L, "Entre los dos suman un treinta y cinco. No basta para vender la empresa. Pero sí para meter a un fondo en el consejo.", "둘을 합치면 35%예요. 회사를 팔기엔 모자라요. 하지만 펀드를 이사회에 들이기엔 충분하죠."),
(A, "Y con el fondo dentro, todo lo demás llega solo. Primero un consejero. Luego un «plan de eficiencia». Luego el horno dos.", "그리고 펀드가 들어오면 나머지는 저절로 따라오죠. 처음엔 이사 한 명. 그다음엔 '효율화 계획'. 그다음엔 2호기."),
(L, "Exacto. Es la página doce. La conozco porque la escribí yo.", "정확해요. 12쪽이에요. 제가 써 봐서 알아요."),
(A, "(respira hondo) Lucas, te lo voy a preguntar una vez y no te lo volveré a preguntar. ¿Te tienta?", "(깊게 숨을 쉬고) 루카스, 한 번만 물을게요. 다시는 안 물어요. 끌려요?"),
(L, "No te voy a engañar: doscientos ochenta mil euros al año tientan a cualquiera. Y Madrid es mi casa.", "속이지 않을게요. 1년에 28만 유로면 누구라도 끌리죠. 그리고 마드리드는 제 고향이에요."),
(A, "Gracias por no mentirme.", "거짓말 안 해 줘서 고마워요."),
(L, "Tampoco habría podido. Me lo habrías notado en la voz.", "할 수도 없었을 거예요. 목소리만 듣고도 알아챘을 테니까."),
(A, "En la voz y en lo que tardas en contestar. Sigue.", "목소리랑 대답하는 데 걸리는 시간으로요. 계속해요."),
(L, "Pero esta noche he sabido que la marca de l'Alcora se fabrica en Turquía. Con el nombre del pueblo en la caja.", "그런데 오늘 밤에 알았어요. 라르코라 브랜드를 튀르키예에서 만든대요. 상자에 마을 이름을 붙여서."),
(A, "(muy bajo) Eso no lo voy a permitir con nuestro nombre.", "(아주 낮게) 우리 이름으로 그런 짓은 절대 못 하게 할 거예요."),
(L, "Yo tampoco. Por eso te llamo a ti antes que a nadie. Ni a tu padre le he dicho nada.", "저도요. 그래서 누구보다 먼저 당신한테 전화한 거예요. 아버님한테도 아직 아무 말 안 했어요."),
(A, "Mañana se lo contamos juntos. No quiero que se entere por una carta de Meridia.", "내일 같이 말해요. 메리디아 편지로 알게 되는 건 싫어요."),
(L, "De acuerdo. Mañana tengo otra reunión con Borja a las nueve. ¿Qué quieres que le diga?", "알겠어요. 내일 9시에 보르하랑 또 만나요. 뭐라고 해 줬으면 좋겠어요?"),
(A, "Lo que quieras. Pero no firmes nada solo.", "하고 싶은 대로요. 하지만 혼자 아무것도 서명하지 마요."),
(L, "Ni una servilleta. Me lo dijiste en Atlanta.", "냅킨 한 장도요. 애틀랜타에서 당신이 한 말이잖아요."),
(A, "(casi sonríe) Veo que tomas apuntes.", "(웃을 뻔하며) 메모를 하나 보네요."),
(L, "De todo lo que importa.", "중요한 건 전부요."),
(A, "Lucas... una cosa más. Lejos de enfadarme contigo, te lo agradezco. Otro habría esperado a tener el contrato en la mano.", "루카스… 하나 더요. 당신한테 화나기는커녕 고마워요. 다른 사람이었으면 계약서를 손에 쥘 때까지 기다렸을 거예요."),
(L, "Otro no tendría una socia que llama a las doce de la noche para decirle que no firme ni servilletas.", "다른 사람한테는 밤 12시에 냅킨에도 서명하지 말라고 하는 동업자가 없겠죠."),
(A, "La que llama eres tú. Buenas noches, socio.", "전화한 건 당신이에요. 잘 자요, 동업자."),
(L, "Buenas noches, socia.", "잘 자요, 동업자."),

("#", "Escena 4 · Jueves 21 de mayo, 9:05 · Meridia Capital", "장면 4 · 5월 21일 목요일 오전 9시 5분 · 메리디아 캐피털"),
(B, "Puntual como siempre. ¿Has dormido bien?", "늘 그렇듯 시간 정확하네. 잘 잤어?"),
(L, "Poco, pero bien. Vengo a decirte que hoy no hay respuesta. La respuesta, si la hay, la dará la familia.", "조금, 하지만 잘 잤어요. 오늘은 대답이 없다는 걸 말하러 왔어요. 대답이 있다면 그건 가족이 할 거예요."),
(B, "La familia somos todos, Lucas. También Xavier. También Teresa.", "가족은 모두야, 루카스. 하비에르도. 테레사도."),
(L, "Por eso mismo. Que decidan ellos. No yo en un despacho de Serrano.", "바로 그래서요. 그분들이 결정하게 해요. 세라노 거리 사무실에 있는 제가 아니라."),
(B, "(cierra la carpeta azul) Como quieras. La oferta sale el lunes. A los cinco accionistas. Y a Xavier, con una nota personal.", "(파란 서류철을 덮으며) 좋을 대로. 제안서는 월요일에 나가. 주주 다섯 명 모두에게. 하비에르한테는 개인 메모까지 붙여서."),
(L, "Entonces nos veremos en junio. De lejos.", "그럼 6월에 보겠네요. 멀리서."),
(B, "¿De lejos? Xavier me ha invitado a la junta como asesor suyo.", "멀리서? 하비에르가 자기 자문으로 나를 주주총회에 초대했는데."),
(L, "Las juntas de los Albalat se hacen en el comedor de Vicente. Ahí no entran asesores. Entran platos de arroz.", "알발라트 집안의 주주총회는 비센테 집 식당에서 해요. 거긴 자문이 못 들어가요. 쌀 요리 접시만 들어가죠."),
(B, "Una última cosa, de excompañero: el que dice que no a un fondo no recibe la segunda llamada.", "마지막으로, 옛 동료로서 하나만. 펀드에 아니라고 한 사람은 두 번째 전화를 받지 못해."),
(L, "Lo sé. Ya me dijeron que no una vez, en l'Alcora, ciento ochenta personas. Ninguna recibió la segunda llamada.", "알아요. 라르코라에서 180명이 이미 한 번 '아니요'를 들었죠. 그중 누구도 두 번째 전화를 받지 못했어요."),
(None, "Lucas sale a la calle. En el móvil, un mensaje de Amparo: «Papá nos espera a las 18:00. Le he dicho solo que es importante». Lucas camina hacia la estación de Atocha.", "루카스가 거리로 나온다. 휴대폰에 암파로의 메시지. '아빠가 6시에 기다려요. 중요한 일이라고만 했어요.' 루카스는 아토차역을 향해 걷는다."),
]

PRE = [
("text", "장면 미리보기", "대화문을 읽기 전에 줄거리를 확인하고, 아래 질문의 답을 찾으며 읽어 보세요.", [
 "비센테의 은퇴 선언 열흘 뒤. 루카스는 마드리드에 불려 간다. 기다리고 있던 사람은 옛 컨설팅 회사 상사 보르하, 지금은 투자펀드 메리디아 캐피털의 파트너다. 그의 제안은 알발라트 지분 60% 인수와 루카스 대표이사 자리. 그런데 메리디아는 2년 전 비센테를 찾아갔던 바로 그 그룹이고, 루카스가 엑셀을 만들었던 라르코라 공장 폐쇄의 그 펀드다. 밤에는 옛 동료 이레네가 라르코라의 뒷이야기를 들려준다. 그리고 자정 직전, 루카스는 약속대로 누구보다 먼저 암파로에게 전화한다.",
 "듣기 질문 ① 메리디아의 제안 조건(가치 평가, 지분, 금액, 루카스의 보수)은 무엇인가? 그 대가로 무엇을 '합리화'하려 하는가?",
 "듣기 질문 ② 이레네가 알려 준 라르코라의 '그 뒤'는 무엇인가? 그 사실이 루카스에게 왜 중요한가?",
 "듣기 질문 ③ 하비에르와 테레사의 지분은 몇 %이고, 암파로는 펀드가 '이사회에 들어오는 것'을 왜 두려워하는가?",
]),
]

